CONTEXT_PATH = ROOT / "data" / "processed" / "comp_context.json"
INSIGHTS_PATH = ROOT / "data" / "processed" / "insights.json"
DATA = (ROOT / "data" / "processed" / "quadchart.json").read_text(encoding="utf-8").replace("</", "<\\/")
NEWS_CONTEXT = (CONTEXT_PATH.read_text(encoding="utf-8") if CONTEXT_PATH.exists() else json.dumps({"contexts": {}})).replace("</", "<\\/")
insight_payload = json.loads(INSIGHTS_PATH.read_text(encoding="utf-8")) if INSIGHTS_PATH.exists() else {"insights": {}}
INSIGHTS = json.dumps({
    "schema_version": insight_payload.get("schema_version"),
    "generated_at": insight_payload.get("generated_at"),
    "data_generated_at": insight_payload.get("data_generated_at"),
    "coverage": insight_payload.get("coverage", {}),
    "insights": insight_payload.get("insights", {}),
}, ensure_ascii=False).replace("</", "<\\/")
